#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <expression>\n", argv[0]);
        return 1;
    }

    char *expression = argv[1];
    int stack[100];
    int top = 0;

    for (int i = 0; i < strlen(expression); i++) {
        char c = expression[i];
        if (c == ' ') continue;
        if (c == '+') {
            if (top < 2) {
                printf("ERROR\n");
                return 1;
            }
            int b = stack[top - 1];
            int a = stack[top - 2];
            stack[top - 2] = a + b;
            top--;
        } else if (c == '-') {
            if (top < 2) {
                printf("ERROR\n");
                return 1;
            }
            int b = stack[top - 1];
            int a = stack[top - 2];
            stack[top - 2] = a - b;
            top--;
        } else if (c == '*') {
            if (top < 2) {
                printf("ERROR\n");
                return 1;
            }
            int b = stack[top - 1];
            int a = stack[top - 2];
            stack[top - 2] = a * b;
            top--;
        } else if (c == '/') {
            if (top < 2) {
                printf("ERROR\n");
                return 1;
            }
            int b = stack[top - 1];
            int a = stack[top - 2];
            if (b == 0) {
                printf("ERROR\n");
                return 1;
            }
            stack[top - 2] = a / b;
            top--;
        } else {
            int num = atoi(&c);
            stack[top] = num;
            top++;
        }
    }

    if (top != 1) {
        printf("ERROR\n");
        return 1;
    }

    printf("%d\n", stack[0]);
    return 0;
}
